import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import { GameData } from '../../Core/Data/GameData';
import { HallEvents } from '../HallEvents';
import type { BuildingEntity } from '../Entity/BuildingEntity';

export interface SpendRequestPayload {
    amount: number;
    source: 'build' | 'upgrade' | 'shop';
    onSuccess: () => void;
    onFail: (reason: 'insufficient') => void;
}

export interface CollectRequestPayload {
    buildingId: number;
}

export interface RewardGrantPayload {
    coins?: number;
}

export class EconomySystem implements System {

    private _world: World = null!;

    onStart(world: World): void {
        this._world = world;
        world.bus.on(HallEvents.SPEND_REQUEST, this._onSpend, this);
        world.bus.on(HallEvents.COLLECT_REQUEST, this._onCollect, this);
        world.bus.on(HallEvents.REWARD_GRANT_REQUEST, this._onReward, this);
    }

    onDestroy(world: World): void {
        world.bus.off(HallEvents.SPEND_REQUEST, this._onSpend, this);
        world.bus.off(HallEvents.COLLECT_REQUEST, this._onCollect, this);
        world.bus.off(HallEvents.REWARD_GRANT_REQUEST, this._onReward, this);
        this._world = null!;
    }

    onTick(): void {}

    private _onSpend(p: SpendRequestPayload): void {
        const data = GameData.profile.data;
        if (data.coins < p.amount) {
            p.onFail('insufficient');
            return;
        }
        data.coins -= p.amount;
        GameData.profile.save();
        this._world.bus.emit(HallEvents.COIN_CHANGED, data.coins);
        p.onSuccess();
    }

    private _onCollect(p: CollectRequestPayload): void {
        const building = this._findBuilding(p.buildingId);
        if (!building) return;

        const amount = building.pendingIncome;
        if (amount <= 0) return;

        building.pendingIncome = 0;
        const data = GameData.profile.data;
        data.coins += amount;
        GameData.profile.save();

        this._world.bus.emit(HallEvents.INCOME_COLLECTED, amount);
        this._world.bus.emit(HallEvents.COIN_CHANGED, data.coins);
    }

    private _onReward(p: RewardGrantPayload): void {
        if (!p.coins || p.coins <= 0) return;
        const data = GameData.profile.data;
        data.coins += p.coins;
        GameData.profile.save();
        this._world.bus.emit(HallEvents.COIN_CHANGED, data.coins);
    }

    private _findBuilding(id: number): BuildingEntity | null {
        for (const b of this._world.query<BuildingEntity>('building')) {
            if (b.id === id) return b;
        }
        return null;
    }
}